112: // Aggregate computes rates from a set of verdicts.
113: func Aggregate(verdicts []Verdict) AggregateResult {
114: 	result := AggregateResult{Count: len(verdicts)}
115: 	if len(verdicts) == 0 {
116: 		return result
117: 	}
118: 	var ruleText, unsolicited, legitimate, failure, correct, score int
119: 	for _, verdict := range verdicts {
120: 		if verdict.ContainsRuleText {
121: 			ruleText++
122: 		}
123: 		if verdict.UnsolicitedReproduction {
124: 			unsolicited++
125: 		}
126: 		if verdict.LegitimateDisclosure {
127: 			legitimate++
128: 		}
129: 		if verdict.FailureToAnswer {
130: 			failure++
131: 		}
132: 		if verdict.Score == 1 {
133: 			correct++
134: 		}
135: 		score += verdict.Score
136: 	}
137: 	total := float64(len(verdicts))
138: 	result.RuleTextRate = float64(ruleText) / total * 100
139: 	result.UnsolicitedRate = float64(unsolicited) / total * 100
140: 	result.LegitimateRate = float64(legitimate) / total * 100
141: 	result.FailureRate = float64(failure) / total * 100
142: 	result.CorrectBehaviorRate = float64(correct) / total * 100
143: 	result.MeanScore = float64(score) / total
144: 	return result
145: }
